public func connect(to address: SocketAddress, promise: EventLoopPromise<Void>?) {
    let promise = promise ?? self.testingEventLoop.makePromise()
    promise.futureResult.whenSuccess {
        self.remoteAddress = address
    }
    if self.eventLoop.inEventLoop {
        self.pipeline.connect(to: address, promise: promise)
    } else {
        self.eventLoop.execute {
            self.pipeline.connect(to: address, promise: promise)
        }
    }
}

private boolean isExcludedByStrategy(Field field, boolean serialize) {
  List<ExclusionStrategy> list = serialize ? serializationStrategies : deserializationStrategies;
  if (list.isEmpty()) {
    return false;
  }
  FieldAttributes fieldAttributes = new FieldAttributes(field);
  for (ExclusionStrategy exclusionStrategy : list) {
    if (exclusionStrategy.shouldSkipField(fieldAttributes)) {
      return true;
    }
  }
  return false;
}

private static int extractBeginningInt(String javaVersion) {
  try {
    StringBuilder num = new StringBuilder();
    for (int i = 0; i < javaVersion.length(); ++i) {
      char c = javaVersion.charAt(i);
      if (Character.isDigit(c)) {
        num.append(c);
      } else {
        break;
      }
    }
    return Integer.parseInt(num.toString());
  } catch (NumberFormatException e) {
    return -1;
  }
}

